import numpy as np
x=np.array([4.98,8.93,12.88,16.83,20.78,24.73,28.68,32.63,36.58,40.53,44.48,48.43,52.38,56.33,60.28,64.23,68.18,72.13,76.08,80.03,
 6.9,14.8,18.8,26.7,34.6,46.45,58.3,70.15,3,82])
y=np.array([10.263,20.780,40.034,54.453,68.785,102.723,143.974,170.868,175.808,199.419,250.705,308.192,292.044,395.640,416.236,485.378,548.567,617.061,708.595,802.241,
 14.668,54.216,57.291,116.032,187.246,287.619,405.666,564.998,4.713,804.428])
o=np.argsort(x); x,y=x[o],y[o]
means={"quad":lambda x:np.column_stack([x,x**2]),"cubic":lambda x:np.column_stack([x,x**2,x**3]),
       "quad+int":lambda x:np.column_stack([np.ones_like(x),x,x**2])}
def fit_sd(x,r,kind):
    if kind=="const": F=np.ones((len(x),1))
    elif kind=="lin": F=np.column_stack([np.ones_like(x),x])
    elif kind=="sqrt": F=np.column_stack([np.ones_like(x),np.sqrt(x)])
    # fit sd = F@s with s>=0 via least squares on |r|*sqrt(pi/2)
    s,*_=np.linalg.lstsq(F,np.abs(r)*np.sqrt(np.pi/2),rcond=None)
    return F,s
def predict_sd(x,s,kind):
    F=np.ones((len(x),1)) if kind=="const" else (np.column_stack([np.ones_like(x),x]) if kind=="lin" else np.column_stack([np.ones_like(x),np.sqrt(x)]))
    return np.maximum(F@s,0.5)
res={}
for mk,mf in means.items():
  for sk in ["const","lin","sqrt"]:
    nll=0; cover=0
    for i in range(len(x)):
        m=np.ones(len(x),bool); m[i]=False
        X=mf(x[m]); c,*_=np.linalg.lstsq(X,y[m],rcond=None)
        r=y[m]-X@c
        _,s=fit_sd(x[m],r,sk)
        mu=mf(np.array([x[i]]))@c; sd=predict_sd(np.array([x[i]]),s,sk)[0]
        nll+=0.5*np.log(2*np.pi*sd**2)+0.5*((y[i]-mu[0])/sd)**2
        cover+= abs(y[i]-mu[0])<=1.96*sd
    res[(mk,sk)]=(nll/len(x),cover/len(x))
for k,v in sorted(res.items(),key=lambda kv:kv[1][0]): print(k,"LOO NLL %.3f coverage %.2f"%v)
